package io.github.miklires.mauction;import org.bukkit.inventory.ItemStack;import org.bukkit.util.io.*;import java.io.*;public final class ItemCodec{private ItemCodec(){}public static byte[]encode(ItemStack item){try(var bytes=new ByteArrayOutputStream();var out=new BukkitObjectOutputStream(bytes)){out.writeObject(item);return bytes.toByteArray();}catch(IOException e){throw new IllegalArgumentException("Cannot serialize item",e);}}public static ItemStack decode(byte[]data){try(var in=new BukkitObjectInputStream(new ByteArrayInputStream(data))){return(ItemStack)in.readObject();}catch(IOException|ClassNotFoundException e){throw new IllegalArgumentException("Cannot deserialize item",e);}}}
